INSERT INTO changelog (title, body, created_at) VALUES ('Центр і Огляд клієнта — загальна картина', 'Центр: під привітанням — «Головне зараз» з «Розвитку» (клік — туди). У «Потребують уваги» зверху — наші продукти з поломками (скільки і в яких клієнтів, клік — «Що виправити»). У плитці «Клієнти» — продажі клієнтів з CRM за 30 днів. Як і раніше влазить в один екран.
Огляд клієнта переробив: зверху 4 цифри — Гроші (борг або абонплата), Реклама за 7 днів (ліди, ціна ліда), Продажі за 30 днів (з CRM), Задачі (в роботі, прострочені) — клік веде в розділ. Далі «Стратегія» і «Памʼять Джері» — коротко, клік відкриває повністю (там же «Зібрати/оновити» і правка). Плитки Послуги, Наші продукти, Telegram, Ідеї — деталі у віконці. Задачі і «Що зроблено» — по 4. Сторінка вдвічі коротша.', datetime('now'));
